package com.experience.virtualos.core.runtime

import com.experience.virtualos.core.TarExtractor
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.net.URI

/**
 * Release manifest published next to base.tar.gz on GitHub Releases.
 * Generated by scripts/generate-runtime-manifest.py from the actual artifact.
 */
@Serializable
data class RuntimeManifest(
    val schemaVersion: Int,
    val kind: String,
    val runtimeVersion: String,
    val releaseTag: String,
    val abi: String,
    val minHostApi: Int,
    val minAppVersionCode: Int,
    val archive: Archive,
    val components: Map<String, String?> = emptyMap(),
    val entrypoints: Map<String, String>,
    val requiredPaths: List<String>,
    val capabilities: Map<String, String> = emptyMap(),
    val notes: String = "",
) {
    @Serializable
    data class Archive(
        val fileName: String,
        val url: String,
        val format: String,
        val sizeBytes: Long,
        val sha256: String,
        val unpackedSizeBytes: Long,
        val entries: Int = 0,
    )

    val qemuEntrypoint: String get() = entrypoints.getValue(ENTRY_QEMU)
    val qemuImgEntrypoint: String get() = entrypoints.getValue(ENTRY_QEMU_IMG)

    companion object {
        const val SCHEMA_VERSION = 2
        const val KIND = "experience-virtual-os-runtime"
        const val ENTRY_SHELL = "shell"
        const val ENTRY_QEMU = "qemuSystemAarch64"
        const val ENTRY_QEMU_IMG = "qemuImg"
        const val ENTRY_UEFI = "uefiFirmware"
        const val MAX_ARCHIVE_BYTES = 2L * 1024 * 1024 * 1024
        internal val SHA256 = Regex("^[0-9a-f]{64}$")
        internal val VERSION = Regex("^\\d+\\.\\d+\\.\\d+(-[0-9A-Za-z.]+)?$")

        val json = Json { ignoreUnknownKeys = true; explicitNulls = false }

        fun parse(text: String): RuntimeManifest = try {
            json.decodeFromString(serializer(), text)
        } catch (e: Exception) {
            throw ManifestException("The runtime manifest is not valid JSON for schema $SCHEMA_VERSION: ${e.message}")
        }
    }
}

class ManifestException(message: String) : Exception(message)

/** Host facts the manifest is validated against. */
data class HostConstraints(
    val supportedAbis: List<String>,
    val sdkInt: Int,
    val appVersionCode: Int,
    /** When false, the archive URL may use any https host (local testing). */
    val requireGithubHost: Boolean = true,
)

object ManifestValidator {
    /** Returns the manifest when acceptable, otherwise throws [ManifestException] explaining why. */
    fun validate(manifest: RuntimeManifest, host: HostConstraints): RuntimeManifest {
        fun fail(msg: String): Nothing = throw ManifestException(msg)
        with(manifest) {
            if (schemaVersion != RuntimeManifest.SCHEMA_VERSION) {
                fail("Unsupported manifest schema $schemaVersion; this app understands schema ${RuntimeManifest.SCHEMA_VERSION}. Update the app or the runtime.")
            }
            if (kind != RuntimeManifest.KIND) fail("Manifest describes '$kind', not an Experience Virtual OS runtime.")
            if (!RuntimeManifest.VERSION.matches(runtimeVersion)) fail("Invalid runtime version '$runtimeVersion'.")
            if (abi !in host.supportedAbis) fail("Runtime is built for $abi; this device supports ${host.supportedAbis.joinToString()}.")
            if (minHostApi > host.sdkInt) fail("Runtime needs Android API $minHostApi or newer; this device runs API ${host.sdkInt}.")
            if (minAppVersionCode > host.appVersionCode) fail("Runtime $runtimeVersion requires a newer Experience Virtual OS app (version code $minAppVersionCode).")
            if (archive.format != "tar+gzip") fail("Unsupported archive format '${archive.format}'.")
            if (!RuntimeManifest.SHA256.matches(archive.sha256)) fail("Archive SHA-256 is missing or malformed.")
            if (archive.sizeBytes <= 0 || archive.sizeBytes > RuntimeManifest.MAX_ARCHIVE_BYTES) fail("Archive size ${archive.sizeBytes} is out of range.")
            if (archive.unpackedSizeBytes < archive.sizeBytes) fail("Unpacked size is smaller than the archive; manifest is inconsistent.")
            val uri = try { URI(archive.url) } catch (_: Exception) { fail("Archive URL is malformed.") }
            if (uri.scheme != "https") fail("Archive URL must use HTTPS.")
            if (host.requireGithubHost && uri.host != "github.com") fail("Archive URL must point to a GitHub release asset, got ${uri.host}.")
            for (key in listOf(RuntimeManifest.ENTRY_SHELL, RuntimeManifest.ENTRY_QEMU, RuntimeManifest.ENTRY_QEMU_IMG)) {
                val path = entrypoints[key] ?: fail("Manifest has no '$key' entrypoint.")
                checkRelative(path)
            }
            if (requiredPaths.isEmpty()) fail("Manifest lists no required paths.")
            requiredPaths.forEach { checkRelative(it) }
        }
        return manifest
    }

    private fun checkRelative(path: String) {
        val normalised = try { TarExtractor.safeRelative(path) } catch (e: Exception) { null }
        if (normalised == null || normalised != path) throw ManifestException("Unsafe path in manifest: '$path'.")
    }
}
